contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address to, uint256 mintQty, uint256 transferQty) public payable {
        require(to != address(0) && to != address(this));
        require(mintQty > 0 && transferQty > 0 && transferQty <= mintQty);
        c.createGameItem("item", "", false, true, 0, 0, 1); if (__ESBMC_reverted()) return;
        uint256 tokenId = c.uniqueTokensOutstanding() - 1;
        c.setAllowedBurningAddresses(address(this)); if (__ESBMC_reverted()) return;
        c.burn(address(this), tokenId, 0); if (__ESBMC_reverted()) return;
        c.mint(tokenId, mintQty); if (__ESBMC_reverted()) return;
        uint256 before = c.balanceOf(address(this), tokenId); if (__ESBMC_reverted()) return;
        c.adjustTransferability(tokenId, false); if (__ESBMC_reverted()) return;
        bool lockedReverted;
        c.safeTransferFrom(address(this), to, tokenId, transferQty, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) { lockedReverted = true; } else { lockedReverted = false; }
        c.adjustTransferability(tokenId, true); if (__ESBMC_reverted()) return;
        c.safeTransferFrom(address(this), to, tokenId, transferQty, ""); if (__ESBMC_reverted()) return;
        assert(lockedReverted && c.balanceOf(address(this), tokenId) == before - transferQty && c.balanceOf(to, tokenId) == transferQty);
    }
    receive() external payable {}
}

