pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(address to, uint256 mintQty, uint256 transferQty) internal {
        vm.assume(to != address(0) && to != address(this));
        vm.assume(mintQty > 0 && transferQty > 0 && transferQty <= mintQty);
        try c.createGameItem("item", "", false, true, 0, 0, 1) {} catch { return; }
        uint256 tokenId = c.uniqueTokensOutstanding() - 1;
        try c.setAllowedBurningAddresses(address(this)) {} catch { return; }
        try c.burn(address(this), tokenId, 0) {} catch { return; }
        try c.mint(tokenId, mintQty) {} catch { return; }
        uint256 before;
        try c.balanceOf(address(this), tokenId) returns (uint256 __r) { before = __r; } catch { return; }
        try c.adjustTransferability(tokenId, false) {} catch { return; }
        bool lockedReverted;
        try c.safeTransferFrom(address(this), to, tokenId, transferQty, "") { lockedReverted = false; } catch { lockedReverted = true; }
        try c.adjustTransferability(tokenId, true) {} catch { return; }
        try c.safeTransferFrom(address(this), to, tokenId, transferQty, "") {} catch { return; }
        assertTrue(lockedReverted && c.balanceOf(address(this), tokenId) == before - transferQty && c.balanceOf(to, tokenId) == transferQty);
    }

    function testFuzz_run(address to, uint256 mintQty, uint256 transferQty) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(to, mintQty, transferQty);
    }

    receive() external payable {}
}
